def comps(a,conn=8):
    seen=set();out=[]
    for r,c in zip(*np.where(a)):
        if (r,c) in seen:continue
        q=[(r,c)];seen.add((r,c)); comp=[]
        while q:
            x,y=q.pop();comp.append((x,y))
            for dx in range(-1,2):
                for dy in range(-1,2):
                    if dx==dy==0 or (conn==4 and abs(dx)+abs(dy)!=1):continue
                    p=(x+dx,y+dy)
                    if 0<=p[0]<a.shape[0] and 0<=p[1]<a.shape[1] and a[p] and p not in seen:seen.add(p);q.append(p)
        out.append(sorted(comp))
    return sorted(out,key=len,reverse=True)
